"""Invoke actual C++ generic range iterators and const indexing."""
CORE=r'''
#include <type_traits>
void circularCheck7(bool ok,const std::string& message){if(!ok)throw std::runtime_error(message);}
template<class T> std::vector<T> circularRead7(const CircularArray<T>& actor,int n){std::vector<T> result;auto iterator=actor.begin();const auto end=actor.end();for(;iterator!=end;++iterator){circularCheck7(result.size()<static_cast<size_t>(n),"Iterators yield exactly the fixed length");T value=*iterator;result.push_back(value);}circularCheck7(result.size()==static_cast<size_t>(n),"Iterators yield exactly the fixed length");return result;}
template<class T> json circularTwice7(const CircularArray<T>& actor,int n){auto first=actor.begin(),second=actor.begin();const auto end=actor.end();std::vector<T> left,right;for(int i=0;i<n;++i){circularCheck7(first!=end&&second!=end,"Independent iterators must not consume each other");left.push_back(*first);right.push_back(*second);++first;++second;}circularCheck7(!(first!=end)&&!(second!=end),"Each iterator finishes at the fixed length");return json::array({left,right});}
template<class T> json circularRun7(const json& row){const auto& args=row["arguments"];auto initial=args[1].get<std::vector<T>>();const auto saved=initial;const std::vector<T>& supplied=initial;int n=static_cast<int>(initial.size());auto newValues=args[4].get<std::vector<T>>();CircularArray<T> actor(supplied);const CircularArray<T>& readonly=actor;static_assert(std::is_same_v<std::decay_t<decltype(readonly.Get(0))>,T>,"Get returns the selected generic element type");static_assert(std::is_same_v<decltype(actor.Set(0,std::declval<const T&>())),void>,"Set returns void");static_assert(std::is_same_v<decltype(actor.Rotate(0)),void>,"Rotate returns void");circularRead7(readonly,n);circularCheck7(initial==saved,"Preserve caller initial values");json results=json::array({nullptr});const auto& operations=args[2];const auto& operands=args[3];for(size_t i=1;i<operations.size();++i){std::string operation=operations[i];int operand=operands[i];bool invalid=(operation=="Get"||operation=="Set")&&(operand<0||operand>=n);auto before=invalid?circularRead7(readonly,n):std::vector<T>{};json result;try{if(operation=="Get"){T value=readonly.Get(operand);result=value;}else if(operation=="Set"){actor.Set(operand,newValues[i]);result=nullptr;}else if(operation=="Rotate"){actor.Rotate(operand);result=nullptr;}else if(operation=="Iterate")result=circularRead7(readonly,n);else if(operation=="IterateTwice")result=circularTwice7(readonly,n);else throw std::runtime_error("Unknown operation");circularCheck7(!invalid,"Invalid indexing must throw out_of_range");}catch(const std::out_of_range& error){if(!invalid)throw;circularCheck7(circularRead7(readonly,n)==before,"Invalid indexing preserves state");result=json{{"error","index"}};}circularCheck7(initial==saved,"Preserve caller initial values during updates");results.push_back(result);}return json{{"actual",{{"results",results},{"finalValues",circularRead7(readonly,n)}}},{"mutationOk",true}};}
json executeCircular7(const json& row){return row["arguments"][0]=="number"?circularRun7<int>(row):circularRun7<std::string>(row);}
'''
